import 'package:flutter/material.dart';
import '../../core/data/outlet_repository.dart';
import '../../shared/irkop_ui.dart';
class OutletsPage extends StatefulWidget{const OutletsPage({super.key,this.businessId});final String? businessId;@override State<OutletsPage> createState()=>_S();}
class _S extends State<OutletsPage>{final r=OutletRepository();late Future<List<OutletRecord>> f;@override void initState(){super.initState();f=load();}Future<List<OutletRecord>> load()=>widget.businessId==null?Future.value(const[]):r.load(widget.businessId!);Future<void> refresh()async{setState(()=>f=load());await f;}Future<void> add()async{final b=widget.businessId;if(b==null)return;final c=TextEditingController();final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(x)=>Padding(padding:EdgeInsets.fromLTRB(16,16,16,MediaQuery.of(x).viewInsets.bottom+16),child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:c,decoration:const InputDecoration(labelText:'Nama outlet',border:OutlineInputBorder())),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Tambah Outlet')))])));if(ok==true&&c.text.trim().isNotEmpty){try{await r.create(businessId:b,name:c.text);await refresh();}finally{c.dispose();}}}
@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:refresh,child:FutureBuilder<List<OutletRecord>>(future:f,builder:(c,s)=>ListView(padding:const EdgeInsets.all(16),children:[IrkopSectionHeader(eyebrow:'Bisnis',title:'Kelola Outlet',subtitle:'Tambah outlet dan atur status aktif.',icon:Icons.storefront_outlined,action:'Tambah Outlet',onAction:add)])));}